Definition hpush_entail_wit_1 := 
(
forall (v_pre: Z) (hsum_pre: Z) (hsize_pre: Z) (heap_pre: Z) (sm: Z) (hs: Z) (l: (@list Z)) (cap: Z) (PreH1 : (0 <= hs)) (PreH2 : (hs < cap)) (PreH3 : (cap <= 200000)) (PreH4 : ((Zlength (l)) = cap)) (PreH5 : (HeapOrdered l hs )) (PreH6 : (sm = (ZSum ((sublist (0) (hs) (l)))))) (PreH7 : forall (i: Z) , (((0 <= i) /\ (i < hs)) -> (((-1000000000000) <= (Znth i l 0)) /\ ((Znth i l 0) <= 1000000000000)))) (PreH8 : ((-1000000000000) <= v_pre)) (PreH9 : (v_pre <= 1000000000000)) (PreH10 : ((-300000000000000000) <= sm)) (PreH11 : (sm <= 300000000000000000)) ,
  (Int64Array.full heap_pre cap (replace_Znth (hs) (v_pre) (l)) )
  **  ((hsize_pre) # Int  |-> (hs + 1 ))
  **  ((hsum_pre) # Int64  |-> (sm + v_pre ))
|--
  EX (cur: (@list Z)) ,
  “ (0 <= hs) ” 
  &&  “ (hs < cap) ” 
  &&  “ (cap <= 200000) ” 
  &&  “ ((Zlength (l)) = cap) ” 
  &&  “ ((Zlength (cur)) = cap) ” 
  &&  “ (0 <= hs) ” 
  &&  “ (hs <= hs) ” 
  &&  “ ((-1000000000000) <= v_pre) ” 
  &&  “ (v_pre <= 1000000000000) ” 
  &&  “ ((-300000000000000000) <= sm) ” 
  &&  “ (sm <= 300000000000000000) ” 
  &&  “ forall (q: Z) , (((0 <= q) /\ (q < (hs + 1 ))) -> (((-1000000000000) <= (Znth q cur 0)) /\ ((Znth q cur 0) <= 1000000000000))) ” 
  &&  “ (PushSiftState l cur hs hs v_pre ) ”
  &&  (Int64Array.full heap_pre cap cur )
  **  ((hsize_pre) # Int  |-> (hs + 1 ))
  **  ((hsum_pre) # Int64  |-> (sm + v_pre ))
) \/
(
forall (v_pre: Z) (sm: Z) (hs: Z) (l: (@list Z)) (cap: Z) (PreH1 : (0 <= hs)) (PreH2 : (hs < cap)) (PreH3 : (cap <= 200000)) (PreH4 : ((Zlength (l)) = cap)) (PreH5 : (HeapOrdered l hs )) (PreH6 : (sm = (ZSum ((sublist (0) (hs) (l)))))) (PreH7 : forall (i: Z) , (((0 <= i) /\ (i < hs)) -> (((-1000000000000) <= (Znth i l 0)) /\ ((Znth i l 0) <= 1000000000000)))) (PreH8 : ((-1000000000000) <= v_pre)) (PreH9 : (v_pre <= 1000000000000)) (PreH10 : ((-300000000000000000) <= sm)) (PreH11 : (sm <= 300000000000000000)) ,
  TT && emp 
|--
  “ (PushSiftState l (replace_Znth (hs) (v_pre) (l)) hs hs v_pre ) ” 
  &&  “ forall (q: Z) , (((0 <= q) /\ (q < (hs + 1 ))) -> (((-1000000000000) <= (Znth q (replace_Znth (hs) (v_pre) (l)) 0)) /\ ((Znth q (replace_Znth (hs) (v_pre) (l)) 0) <= 1000000000000))) ” 
  &&  “ ((Zlength ((replace_Znth (hs) (v_pre) (l)))) = cap) ”
  &&  emp
).

